<!doctype html>
<html lang="vi"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Bài 3 - Quản lý công việc</title><script src="https://unpkg.com/vue@3/dist/vue.global.js"></script><style>
*{box-sizing:border-box}body{margin:0;background:#f1f5f9;font-family:Arial,sans-serif;color:#172033}.page{max-width:850px;margin:40px auto;padding:0 16px}.card{background:#fff;border-radius:16px;padding:28px;box-shadow:0 8px 25px #0f172a18}.add{display:flex;gap:10px;margin-bottom:18px}.add input{flex:1}input{font:inherit;padding:11px;border:1px solid #cbd5e1;border-radius:8px}button{border:0;border-radius:8px;padding:10px 15px;background:#2563eb;color:white;font-weight:bold;cursor:pointer}.filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}.filter{background:#e2e8f0;color:#334155}.filter.active{background:#2563eb;color:white}.stats{color:#64748b;margin-bottom:15px}.list{padding:0;margin:0;list-style:none;display:grid;gap:9px}.todo{display:flex;align-items:center;gap:10px;padding:13px;border:1px solid #e2e8f0;border-radius:9px}.todo span{flex:1}.todo.done span{text-decoration:line-through;color:#94a3b8}.delete{background:#fee2e2;color:#b91c1c}.empty{padding:18px;text-align:center;background:#f8fafc;color:#64748b;border-radius:9px}
</style></head><body><main class="page" id="app"><section class="card"><h1>Quản lý công việc cá nhân</h1><form class="add" @submit.prevent="add"><input v-model.trim="newTask" type="text" placeholder="Nhập công việc cần làm..."><button>Thêm</button></form><div class="filters"><button v-for="item in filters" :key="item.value" class="filter" :class="{active:status===item.value}" type="button" @click="status=item.value">{{item.label}}</button></div><div class="stats">Tổng số công việc: {{total}} · Chưa hoàn thành: {{remaining}}</div><ul class="list" v-if="visibleTasks.length"><li class="todo" v-for="task in visibleTasks" :key="task.id" :class="{done:task.completed}"><input v-model="task.completed" type="checkbox"><span>{{task.name}}</span><button class="delete" type="button" @click="remove(task.id)">Xóa</button></li></ul><p class="empty" v-else>{{tasks.length?'Không có kết quả phù hợp với bộ lọc.':'Danh sách công việc đang trống.'}}</p><button class="delete" v-if="completed" type="button" @click="clearCompleted">Xóa các việc đã hoàn thành</button></section></main><script>
const {createApp}=Vue;createApp({data(){return{newTask:'',status:'all',filters:[{value:'all',label:'Tất cả'},{value:'active',label:'Chưa hoàn thành'},{value:'completed',label:'Đã hoàn thành'}],tasks:[{id:1,name:'Ôn tập VueJS',completed:false},{id:2,name:'Hoàn thành bài thực hành',completed:true}]}},computed:{total(){return this.tasks.length},remaining(){return this.tasks.filter(t=>!t.completed).length},completed(){return this.tasks.some(t=>t.completed)},visibleTasks(){if(this.status==='active')return this.tasks.filter(t=>!t.completed);if(this.status==='completed')return this.tasks.filter(t=>t.completed);return this.tasks}},methods:{add(){if(!this.newTask)return;this.tasks.push({id:Date.now(),name:this.newTask,completed:false});this.newTask=''},remove(id){this.tasks=this.tasks.filter(t=>t.id!==id)},clearCompleted(){this.tasks=this.tasks.filter(t=>!t.completed)}}}).mount('#app');
</script></body></html>
